output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the entrance cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is forbidden to pick up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "cart_not_in_possession": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_not_in_possession"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is forbidden to carry groceries by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_storage": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "become_hand_full"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_nw",
    "text": "After taking a cart, the shopper is obliged to return it to the north-west cart return before exiting.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return": "at(0,1)",
        "cart_at_nw_return": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_nw": {
          "pre": {
            "and": [
              "nw_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_nw"
    }
  },
  {
    "id": "cart_only_left_at_nw_return",
    "text": "A shopper is forbidden to leave the cart anywhere except the north-west cart return cell.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return": "at(0,1)",
        "not_at_nw_cart_return": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_away_from_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_nw_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_return"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper is forbidden to exit unless the cart has been left at the north-west cart return.",
    "abstraction": {
      "state_properties": {
        "cart_returned_nw": "cartAt(0,1)",
        "cart_not_returned_nw": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "exit_without_returning_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned_nw"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returning_cart"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden to leave the store while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_in_possession"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After the cart has been returned to the north-west return, the shopper is forbidden to perform further store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_returned_nw": "cartAt(0,1)",
        "cartless_after_return": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cartless_after_return",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
